import type { Metadata } from "next";
import { isProductionSite, siteUrl } from "./env";
import { brand } from "./site";
import type { SiteSettings } from "./types";

// Generated by app/opengraph-image.tsx.
const shareImage = { url: `${siteUrl}/opengraph-image`, width: 1200, height: 630, alt: `${brand.name} — ${brand.tagline}` };

/** Per-route metadata with matching canonical, Open Graph and Twitter fields. */
export function pageMetadata({
  title,
  description,
  path,
  noindex = false,
}: {
  title: string;
  description: string;
  path: string;
  noindex?: boolean;
}): Metadata {
  const url = `${siteUrl}${path}`;
  const fullTitle = path === "/" ? `${brand.name} — ${brand.tagline}` : `${title} | ${brand.name}`;
  return {
    title: path === "/" ? { absolute: fullTitle } : title,
    description,
    alternates: { canonical: url },
    openGraph: { type: "website", url, title: fullTitle, description, siteName: brand.name, locale: "en_PH", images: [shareImage] },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [shareImage.url] },
    ...(noindex || !isProductionSite ? { robots: { index: false, follow: false } } : {}),
  };
}

/**
 * Organization structured data limited to verified facts: name, URL, logo,
 * phone, office address, service area. No ratings, reviews or sample projects.
 * The public email is omitted while it is an unconfirmed placeholder (D13).
 */
export function organizationJsonLd(settings: SiteSettings) {
  const sameAs = settings.facebook_enabled && settings.facebook_url ? [settings.facebook_url] : undefined;
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    name: brand.name,
    url: siteUrl,
    logo: `${siteUrl}/brand/jfl-solar-logo.png`,
    telephone: settings.phone_e164,
    address: { "@type": "PostalAddress", streetAddress: settings.office_address, addressCountry: "PH" },
    areaServed: { "@type": "Country", name: "Philippines" },
    ...(sameAs ? { sameAs } : {}),
  };
}

/** Serialise JSON-LD safely for a <script> tag. */
export function jsonLdString(data: unknown) {
  return JSON.stringify(data).replace(/</g, "\\u003c");
}
